 const a=actor(role), all=[a,representative]; return { hierarchy:{async getUser(id){return all.find(u=>u.id===id) as any||null},async getDirectReports(id){return all.filter(u=>u.managerId===id) as any},async getAllUsers(){return all as any},async getRolePermissions(){return null}}, async getGeographyCatalog(){return {countries:[{id:"C1",name:"Country One"}],districts:[{id:"D1",name:"District One",countryId:"C1"}],cities:[{id:"CT1",name:"City One",countryId:"C1",districtId:"D1"}],areas:[{id:"A1",name:"Area One",countryId:"C1",districtId:"D1",cityId:"CT1"}],nodes:[{countryId:"C1",regionId:"D1",districtId:"D1",cityId:"CT1",areaId:"A1",active:true}]}},async getTerritoryAssignments(ids){return assignments.filter(x=>ids.includes(x.userId)) as any},async getProductAssignments(ids){return products.filter(x=>ids.includes(x.userId)) as any},async getProducts(){return [{id:"P1",name:"P",brand:"P",therapeuticArea:"T",price:1,stock:1,isActive:true,promotionGroupId:"G1"}] as any}};
