 it("Package B1 creates one immutable snapshot before revision and never accepts weights",async()=>{const repo=repository();await disagreement(repo);const opened=await openSupervisorAppraisalRevision("SUP",{appraisalId:"A",expectedWorkflowVersion:2},{repository:repo,scopeRepository:scope(Role.MEDICAL_SUPERVISOR),now:()=>"T4"});expect(opened.appraisal).toMatchObject({status:"DRAFT",workflowPhase:"REVISION_DRAFT",revisionCount:1,preRevisionSnapshot:{scores:{productKnowledge:4},comments:{productKnowledge:"Original"},strengths:"Original strength",sourceWorkflowVersion:2,createdAt:"T4"}});const frozen=structuredClone(opened.appraisal.preRevisionSnapshot),saved=await saveSupervisorAppraisalRevision("SUP",{appraisalId:"A",expectedWorkflowVersion:3,...revisionInput({scores:{...completeMedicalScores,productKnowledge:2},comments:{productKnowledge:"Revised"},strengths:"Revised strength",overallRating:3.5})},{repository:repo,scopeRepository:scope(Role.MEDICAL_SUPERVISOR)});expect(saved.appraisal.preRevisionSnapshot).toEqual(frozen);expect(saved.appraisal.sectionWeights).toEqual({knowledge:35,communication:25,professionalism:10,productivity:30});await expect(openSupervisorAppraisalRevision("SUP",{appraisalId:"A",expectedWorkflowVersion:4},{repository:repo,scopeRepository:scope(Role.MEDICAL_SUPERVISOR)})).rejects.toMatchObject({code:"INVALID_APPRAISAL_STATE_TRANSITION"})});
 it("Package B1 revised appraisal has one final acknowledgement and no second loop",async()=>{const repo=repository();await disagreement(repo);const opened=await openSupervisorAppraisalRevision("SUP",{appraisalId:"A",expectedWorkflowVersion:2},{repository:repo,scopeRepository:scope(Role.MEDICAL_SUPERVISOR)}),saved=await saveSupervisorAppraisalRevision("SUP",{appraisalId:"A",expectedWorkflowVersion:opened.appraisal.workflowVersion!,...revisionInput({scores:{...completeMedicalScores,productKnowledge:3},overallRating:3.8})},{repository:repo,scopeRepository:scope(Role.MEDICAL_SUPERVISOR)}),submitted=await submitSupervisorAppraisalRevision("SUP",{appraisalId:"A",expectedWorkflowVersion:saved.appraisal.workflowVersion!},{repository:repo,scopeRepository:scope(Role.MEDICAL_SUPERVISOR)});expect(submitted.appraisal.workflowPhase).toBe("FINAL_REPRESENTATIVE_REVIEW");await expect(finalReviewSupervisorAppraisal("REP",{appraisalId:"A",expectedWorkflowVersion:submitted.appraisal.workflowVersion!,reviewDecision:"MAINTAIN_DISAGREEMENT",representativeComment:"crafted request"},{repository:repo,scopeRepository:representativeScope()})).rejects.toMatchObject({code:"INVALID_FINAL_REPRESENTATIVE_REVIEW_DECISION"});const final=await finalReviewSupervisorAppraisal("REP",{appraisalId:"A",expectedWorkflowVersion:submitted.appraisal.workflowVersion!,reviewDecision:"ACKNOWLEDGE_REVISED_APPRAISAL",representativeComment:"Reviewed"},{repository:repo,scopeRepository:representativeScope()});expect(final.appraisal).toMatchObject({workflowPhase:"SUPERVISOR_FINAL_REVIEW",finalRepresentativeReviewDecision:"ACKNOWLEDGE_REVISED_APPRAISAL",representativeReviewDecision:"DISAGREE_REQUEST_REVIEW",revisionCount:1});await expect(reviewSupervisorAppraisal("REP",{appraisalId:"A",expectedWorkflowVersion:final.appraisal.workflowVersion!,reviewDecision:"DISAGREE_REQUEST_REVIEW",representativeComment:"again"},{repository:repo,scopeRepository:representativeScope()})).rejects.toMatchObject({code:"INVALID_APPRAISAL_STATE_TRANSITION"})});
 it("Package B1 final sign-off preserves snapshot and makes the revised appraisal immutable",async()=>{const repo=repository();await disagreement(repo);const opened=await openSupervisorAppraisalRevision("SUP",{appraisalId:"A",expectedWorkflowVersion:2},{repository:repo,scopeRepository:scope(Role.MEDICAL_SUPERVISOR)}),submitted=await submitSupervisorAppraisalRevision("SUP",{appraisalId:"A",expectedWorkflowVersion:opened.appraisal.workflowVersion!},{repository:repo,scopeRepository:scope(Role.MEDICAL_SUPERVISOR)}),reviewed=await finalReviewSupervisorAppraisal("REP",{appraisalId:"A",expectedWorkflowVersion:submitted.appraisal.workflowVersion!,reviewDecision:"ACKNOWLEDGE_REVISED_APPRAISAL",representativeComment:""},{repository:repo,scopeRepository:representativeScope()}),snapshot=structuredClone(reviewed.appraisal.preRevisionSnapshot),signed=await signOffSupervisorAppraisal("SUP",{appraisalId:"A",expectedWorkflowVersion:reviewed.appraisal.workflowVersion!},{repository:repo,scopeRepository:scope(Role.MEDICAL_SUPERVISOR)});expect(signed.appraisal).toMatchObject({status:"SIGNED_OFF",workflowPhase:"FINALIZED",revisionCount:1});expect(signed.appraisal.preRevisionSnapshot).toEqual(snapshot);await expect(saveSupervisorAppraisalRevision("SUP",{appraisalId:"A",expectedWorkflowVersion:signed.appraisal.workflowVersion!,...revisionInput()},{repository:repo,scopeRepository:scope(Role.MEDICAL_SUPERVISOR)})).rejects.toMatchObject({code:"INVALID_APPRAISAL_STATE_TRANSITION"})});
