 it("Package B1 cancellation voids a revision with versioned phase and revision history while preserving its snapshot",async()=>{const repo=repository();await disagreement(repo);const opened=await openSupervisorAppraisalRevision("SUP",{appraisalId:"A",expectedWorkflowVersion:2},{repository:repo,scopeRepository:scope(Role.MEDICAL_SUPERVISOR)}),snapshot=structuredClone(opened.appraisal.preRevisionSnapshot);await transitionSupervisorVisit("SUP",{visitId:"V",action:"CANCEL",outcome:"",notes:"Cancelled"},{repository:repo,scopeRepository:scope(Role.MEDICAL_SUPERVISOR),now:()=>"T5"});expect(opened.appraisal).toMatchObject({status:"VOID",workflowPhase:"VOID",workflowVersion:4,revisionCount:1,preRevisionSnapshot:snapshot});expect(opened.appraisal.workflowHistory?.at(-1)).toMatchObject({fromStatus:"DRAFT",toStatus:"VOID",action:"VOID",fromPhase:"REVISION_DRAFT",toPhase:"VOID",previousWorkflowVersion:3,workflowVersion:4,revisionNumber:1,actorUid:"SUP",actorRole:Role.MEDICAL_SUPERVISOR,occurredAt:"T5"})});
